import{_ as d,C as i,o as l,c as r,j as t,a as o,E as c,a2 as a}from"./chunks/framework.CdvW4CUT.js";const y=JSON.parse('{"title":"Font Config & Test Screens (dev.anvilcraft.lib.v2.font.screen)","description":"","frontmatter":{},"headers":[],"relativePath":"en/1.21.1/font/screens.md","filePath":"en/1.21.1/font/screens.md"}'),s={name:"en/1.21.1/font/screens.md"};function g(p,e,h,f,u,b){const n=i("BranchContextCard");return l(),r("div",null,[e[0]||(e[0]=t("h1",{id:"font-config-test-screens-dev-anvilcraft-lib-v2-font-screen",tabindex:"-1"},[o("Font Config & Test Screens ("),t("code",null,"dev.anvilcraft.lib.v2.font.screen"),o(") "),t("a",{class:"header-anchor",href:"#font-config-test-screens-dev-anvilcraft-lib-v2-font-screen","aria-label":'Permalink to "Font Config & Test Screens (`dev.anvilcraft.lib.v2.font.screen`)"'},"​")],-1)),c(n,{branch:"1.21.1"}),e[1]||(e[1]=a('<p><code>module.font</code> includes a visual client font config screen <strong><code>FontConfigScreen</code></strong>, a multi-language/multi-style layout test screen <strong><code>FontTestScreen</code></strong>, and a general-purpose scrollable dropdown widget <strong><code>Dropdown</code></strong> with click-shielding.</p><p>Players can open <strong>Mods -&gt; AnvilLib Font (<code>anvillib_font</code>) -&gt; Config</strong> from the main menu to switch system font families and weights and preview SDF rendering live.</p><hr><h2 id="_1-screen-dropdown-widget-api-reference" tabindex="-1">1. Screen &amp; Dropdown Widget API Reference <a class="header-anchor" href="#_1-screen-dropdown-widget-api-reference" aria-label="Permalink to &quot;1. Screen &amp; Dropdown Widget API Reference&quot;">​</a></h2><h3 id="_1-fontconfigscreen-fonttestscreen-apistatus-internal" tabindex="-1">1. <code>FontConfigScreen</code> &amp; <code>FontTestScreen</code> (<code>@ApiStatus.Internal</code>) <a class="header-anchor" href="#_1-fontconfigscreen-fonttestscreen-apistatus-internal" aria-label="Permalink to &quot;1. `FontConfigScreen` &amp; `FontTestScreen` (`@ApiStatus.Internal`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Class</th><th style="text-align:left;">Constructor Signature</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>FontConfigScreen</code></strong></td><td style="text-align:left;"><code>public FontConfigScreen(final ModContainer ignored, final Screen parent)</code></td><td style="text-align:left;">Main font config screen registered on <code>IConfigScreenFactory</code>. Provides linked &quot;Family&quot; and &quot;Font&quot; dropdowns, previews the selected font live via <code>guiGraphics.anvillib$centeredText</code>, and auto-saves to <code>config/anvillib_font.json</code> on change.</td></tr><tr><td style="text-align:left;"><strong><code>FontTestScreen</code></strong></td><td style="text-align:left;"><code>public FontTestScreen(final Screen parent)</code></td><td style="text-align:left;">Entered via the &quot;Test&quot; button on the config screen. Side-by-side comparison of <strong>vanilla bitmap font (<code>GuiGraphics#drawString</code>)</strong> vs <strong>AnvilLib SDF font (<code>GuiGraphics#anvillib$*</code>)</strong> across plain text, colored bold/italic/underline/strikethrough <code>Component</code>s, obfuscated text, centered text, backdrop text, and English/Chinese word wrap.</td></tr></tbody></table><hr><h3 id="_2-dropdown-scrollable-dropdown-with-occlusion-shielding" tabindex="-1">2. <code>Dropdown</code> (Scrollable Dropdown with Occlusion Shielding) <a class="header-anchor" href="#_2-dropdown-scrollable-dropdown-with-occlusion-shielding" aria-label="Permalink to &quot;2. `Dropdown` (Scrollable Dropdown with Occlusion Shielding)&quot;">​</a></h3><p>Located in <code>dev.anvilcraft.lib.v2.font.screen.widget.Dropdown</code> (marked <code>@Beta</code>), extending <code>AbstractWidget</code> and implementing <code>Renderable</code>, <code>GuiEventListener</code>, and <code>NarratableEntry</code>.</p><h4 id="key-inner-records-interfaces" tabindex="-1">Key Inner Records &amp; Interfaces <a class="header-anchor" href="#key-inner-records-interfaces" aria-label="Permalink to &quot;Key Inner Records &amp; Interfaces&quot;">​</a></h4><ul><li><code>Dropdown.DropdownEntry(String id, Component label)</code>: dropdown item record with static factories: <ul><li><code>DropdownEntry.create(String id, Component label)</code></li><li><code>DropdownEntry.create(String id, String label)</code></li></ul></li><li><code>Dropdown.Shielding</code>: occlusion shield blocking hover and click events on underlying widgets outside the expanded dropdown area.</li></ul><h4 id="public-constructors-methods" tabindex="-1">Public Constructors &amp; Methods <a class="header-anchor" href="#public-constructors-methods" aria-label="Permalink to &quot;Public Constructors &amp; Methods&quot;">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">Constructor / Method Signature</th><th style="text-align:left;">Return Type</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>public Dropdown(int x, int y, int width, int height, int screenWidth, int screenHeight, Component message)</code><br><code>public Dropdown(int x, int y, int width, int height, int screenWidth, int screenHeight, Component message, List&lt;DropdownEntry&gt; allow)</code></td><td style="text-align:left;"><code>Dropdown</code></td><td style="text-align:left;">Creates a dropdown widget (popup max height <code>120px</code>, row height <code>18px</code>, automatically expanding downward or upward based on <code>screenHeight</code>).</td></tr><tr><td style="text-align:left;"><code>public void setAllow(List&lt;DropdownEntry&gt; allow)</code></td><td style="text-align:left;"><code>void</code></td><td style="text-align:left;">Updates candidate entries, switching to the first entry if the current selection is absent.</td></tr><tr><td style="text-align:left;"><code>public @Nullable DropdownEntry getValue()</code> / <code>public String getValueId()</code></td><td style="text-align:left;"><code>DropdownEntry</code> / <code>String</code></td><td style="text-align:left;">Returns the selected entry or its ID (<code>getValueId()</code> returns <code>&quot;&quot;</code> when unselected).</td></tr><tr><td style="text-align:left;"><code>public void setValue(@Nullable DropdownEntry value)</code> / <code>public void setValue(@Nullable String id)</code></td><td style="text-align:left;"><code>void</code></td><td style="text-align:left;">Sets the current selection (fires <code>onValueChanged</code> if changed and set).</td></tr><tr><td style="text-align:left;"><code>public void setOnValueChanged(@Nullable Consumer&lt;@Nullable DropdownEntry&gt; onValueChanged)</code></td><td style="text-align:left;"><code>void</code></td><td style="text-align:left;">Sets the selection change listener.</td></tr><tr><td style="text-align:left;"><code>public void setPlaceholder(Component placeholder)</code></td><td style="text-align:left;"><code>void</code></td><td style="text-align:left;">Sets placeholder text when nothing is selected (defaults to <code>&quot;Select...&quot;</code>).</td></tr><tr><td style="text-align:left;"><code>public void setMaxPopupHeight(int maxPopupHeight)</code></td><td style="text-align:left;"><code>void</code></td><td style="text-align:left;">Sets max popup height in pixels (clamped to at least one row <code>18px</code>).</td></tr><tr><td style="text-align:left;"><code>public void setOnShieldingAdd(Consumer&lt;Shielding&gt;)</code><br><code>public void setOnShieldingRemove(Runnable)</code><br><code>public void setShieldingGetter(Supplier&lt;Shielding&gt;)</code></td><td style="text-align:left;"><code>void</code></td><td style="text-align:left;">Binds parent <code>Screen</code> shielding callbacks to prevent click-through between multiple dropdowns.</td></tr></tbody></table>',13))])}const w=d(s,[["render",g]]);export{y as __pageData,w as default};
